// Soporte para múltiples formatos de payload de Evolution API
const payload = $input.first().json.body || $input.first().json;

// Extraer texto del mensaje (varios tipos)
const message =
  payload?.data?.message?.conversation ||
  payload?.data?.message?.extendedTextMessage?.text ||
  payload?.data?.message?.imageMessage?.caption ||
  payload?.data?.message?.videoMessage?.caption ||
  '';

// Extraer datos del remitente
const remoteJid = payload?.data?.key?.remoteJid || '';
const fromMe = payload?.data?.key?.fromMe === true;
const isGroup = remoteJid.includes('@g.us');
const phone = remoteJid.split('@')[0];

// Filtrar mensajes inválidos: vacíos, propios, de grupos
if (!message.trim() || fromMe || isGroup || !phone) {
  return [];
}

return [{
  json: {
    phone,
    usuario: phone,
    message: message.trim()
  }
}];

const { phone, usuario, message } = $input.first().json;

// Prompt optimizado para minimizar tokens con gpt-4o-mini
const systemPrompt = `Eres un parser de intenciones. Analiza el mensaje y responde SOLO JSON válido sin markdown ni texto extra.

RESPUESTAS:

GASTO (menciona monto/precio/$USD/gasté/compré/costó):
{"intent":"registrar_gasto","data":{"descripcion":"descripcion corta","categoria":"comida|transporte|servicios|entretenimiento|salud|hogar|otros","monto":0}}

COMIDA (alimento sin monto en $):
{"intent":"registrar_comida","data":{"alimento":"nombre del alimento","cantidad":"cantidad estimada","calorias_estimadas":0}}

COMANDO:
{"intent":"comando","data":{"nombre":"resumen"}} → usuario escribe: resumen
{"intent":"comando","data":{"nombre":"gastos_hoy"}} → usuario escribe: gastos hoy / mis gastos
{"intent":"comando","data":{"nombre":"calorias_hoy"}} → usuario escribe: calorias / calorias hoy / mi dieta

INDEFINIDO:
{"intent":"fallback","data":{}}

Responde SOLO el JSON.`;

return [{
  json: {
    phone,
    usuario,
    message,
    openaiBody: {
      model: 'gpt-4o-mini',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: message }
      ],
      max_tokens: 120,
      temperature: 0,
      response_format: { type: 'json_object' }
    }
  }
}];

const openaiResponse = $input.first().json;
const prepareData = $('Prepare OpenAI Request').first().json;

const { phone, usuario, message } = prepareData;

let parsed = { intent: 'fallback', data: {} };

try {
  const content = openaiResponse.choices?.[0]?.message?.content || '{}';
  const raw = JSON.parse(content);

  const validIntents = ['registrar_gasto', 'registrar_comida', 'comando', 'fallback'];
  if (validIntents.includes(raw.intent) && typeof raw.data === 'object') {
    parsed = raw;
  }
} catch (e) {
  // Mantener fallback si hay error de parseo
  console.log('Error parsing OpenAI response:', e.message);
}

// Validaciones adicionales por tipo de intent
if (parsed.intent === 'registrar_gasto') {
  if (!parsed.data.monto || isNaN(Number(parsed.data.monto))) {
    parsed = { intent: 'fallback', data: {} };
  } else {
    parsed.data.monto = Number(parsed.data.monto);
    parsed.data.descripcion = parsed.data.descripcion || 'Sin descripción';
    parsed.data.categoria = parsed.data.categoria || 'otros';
  }
}

if (parsed.intent === 'registrar_comida') {
  parsed.data.alimento = parsed.data.alimento || 'Alimento';
  parsed.data.cantidad = parsed.data.cantidad || '1 porción';
  parsed.data.calorias_estimadas = Number(parsed.data.calorias_estimadas) || 0;
}

return [{
  json: {
    phone,
    usuario,
    message,
    intent: parsed.intent,
    data: parsed.data
  }
}];

const parseData = $('Parse AI Response').first().json;
const { phone, data } = parseData;

const categoria = data.categoria ? ` _(${data.categoria})_` : '';
const responseText = `💸 *Gasto registrado*\n${data.descripcion}${categoria}\n$ ${data.monto} UYU`;

return [{ json: { phone, responseText } }];

const parseData = $('Parse AI Response').first().json;
const { phone, data } = parseData;

const cantidad = data.cantidad ? ` (${data.cantidad})` : '';
const responseText = `🍽 *Comida registrada*\n${data.alimento}${cantidad}\n${data.calorias_estimadas} kcal`;

return [{ json: { phone, responseText } }];

const parseData = $('Parse AI Response').first().json;
const { phone, usuario } = parseData;

const today = new Date().toISOString().split('T')[0];
const startOfDay = `${today}T00:00:00`;
const endOfDay = `${today}T23:59:59`;

const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_KEY;
const headers = {
  'apikey': supabaseKey,
  'Authorization': `Bearer ${supabaseKey}`
};

let gastos = [], comidas = [];

try {
  const [gastosRes, comidasRes] = await Promise.all([
    fetch(`${supabaseUrl}/rest/v1/gastos?select=monto,descripcion,categoria&usuario=eq.${usuario}&fecha=gte.${startOfDay}&fecha=lte.${endOfDay}&order=fecha.desc`, { headers }),
    fetch(`${supabaseUrl}/rest/v1/comidas?select=calorias,alimento,cantidad&usuario=eq.${usuario}&fecha=gte.${startOfDay}&fecha=lte.${endOfDay}&order=fecha.desc`, { headers })
  ]);
  gastos = await gastosRes.json();
  comidas = await comidasRes.json();
} catch (e) {
  console.log('Error querying Supabase:', e.message);
}

const totalGastos = Array.isArray(gastos) ? gastos.reduce((s, g) => s + (Number(g.monto) || 0), 0) : 0;
const totalCalorias = Array.isArray(comidas) ? comidas.reduce((s, c) => s + (Number(c.calorias) || 0), 0) : 0;

const gastosLineas = Array.isArray(gastos) && gastos.length > 0
  ? gastos.map(g => `  • ${g.descripcion}: $${g.monto}`).join('\n')
  : '  Sin gastos registrados hoy';

const comidasLineas = Array.isArray(comidas) && comidas.length > 0
  ? comidas.map(c => `  • ${c.alimento} (${c.cantidad}): ${c.calorias} kcal`).join('\n')
  : '  Sin comidas registradas hoy';

const fecha = new Date().toLocaleDateString('es-UY', { weekday: 'long', day: 'numeric', month: 'long' });

const responseText = `📊 *Resumen del día*\n_${fecha}_\n\n💸 *Gastos: $${totalGastos.toFixed(0)} UYU*\n${gastosLineas}\n\n🍽 *Calorías: ${totalCalorias} kcal*\n${comidasLineas}`;

return [{ json: { phone, responseText } }];

