  ? gastos.map(g => `  • ${g.descripcion} _(${g.categoria})_: $${g.monto}`).join('\n')
  : '  Sin gastos registrados hoy';

const fecha = new Date().toLocaleDateString('es-UY', { day: 'numeric', month: 'long' });

const responseText = `💸 *Gastos del ${fecha}*\n\n${lineas}\n\n*Total: $${total.toFixed(0)} UYU*`;

return [{ json: { phone, responseText } }];

const parseData = $('Parse AI Response').first().json;
const { phone, usuario } = parseData;

const today = new Date().toISOString().split('T')[0];
const startOfDay = `${today}T00:00:00`;
const endOfDay = `${today}T23:59:59`;

const supabaseUrl = $env.SUPABASE_URL;
const supabaseKey = $env.SUPABASE_KEY;
const headers = {
  'apikey': supabaseKey,
  'Authorization': `Bearer ${supabaseKey}`
};

let comidas = [];
try {
  const res = await fetch(
    `${supabaseUrl}/rest/v1/comidas?select=calorias,alimento,cantidad&usuario=eq.${usuario}&fecha=gte.${startOfDay}&fecha=lte.${endOfDay}&order=fecha.desc`,
    { headers }
  );
  comidas = await res.json();
} catch (e) {
  console.log('Error querying comidas:', e.message);
}

const totalCalorias = Array.isArray(comidas) ? comidas.reduce((s, c) => s + (Number(c.calorias) || 0), 0) : 0;

const lineas = Array.isArray(comidas) && comidas.length > 0
  ? comidas.map(c => `  • ${c.alimento} (${c.cantidad}): ${c.calorias} kcal`).join('\n')
  : '  Sin comidas registradas hoy';

// Referencia aproximada: 2000 kcal promedio diario
const meta = 2000;
const diferencia = meta - totalCalorias;
const estadoMeta = diferencia >= 0
  ? `${diferencia} kcal restantes para la meta`
  : `${Math.abs(diferencia)} kcal sobre la meta`;

const fecha = new Date().toLocaleDateString('es-UY', { day: 'numeric', month: 'long' });

const responseText = `🍽 *Calorías del ${fecha}*\n\n${lineas}\n\n*Total: ${totalCalorias} kcal*\n_${estadoMeta} (meta: ${meta} kcal)_`;

return [{ json: { phone, responseText } }];

const parseData = $('Parse AI Response').first().json;
const { phone } = parseData;

const responseText = `🤖 No entendí el mensaje. Podés registrar:\n\n💸 *Gastos:* cafe 120 / uber 350 / gasté 400 en nafta\n🍽 *Comidas:* pizza 2 porciones / desayuno cafe y tostadas\n📊 *Comandos:* resumen / gastos hoy / calorias hoy`;

